'use strict';

const express = require('express');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
//
// Supports a structured rule DSL instead of executing arbitrary JS.
//
// Rule format:
//   { "op": "<operator>", "field": "<dot.path>", "value": <literal> }
//
// Compound rules (logical):
//   { "op": "and", "rules": [ <rule>, ... ] }
//   { "op": "or",  "rules": [ <rule>, ... ] }
//   { "op": "not", "rule":  <rule> }
//
// Supported comparison operators:
//   eq, neq, gt, gte, lt, lte, in, nin, contains, startsWith, endsWith
//
// Example request body:
//   {
//     "rule": { "op": "gt", "field": "amount", "value": 100 },
//     "context": { "amount": 150 }
//   }
// ---------------------------------------------------------------------------

/**
 * Safely retrieve a nested value from an object using a dot-separated path.
 * Returns `undefined` if any segment along the path is missing.
 *
 * @param {object} obj   - The context object to read from.
 * @param {string} path  - Dot-separated field path, e.g. "user.address.city".
 * @returns {*}
 */
function getField(obj, path) {
  if (typeof path !== 'string') {
    throw new TypeError(`field must be a string, got ${typeof path}`);
  }
  return path.split('.').reduce(
    (acc, key) => (acc != null && Object.prototype.hasOwnProperty.call(acc, key) ? acc[key] : undefined),
    obj,
  );
}

/**
 * Evaluate a single rule node against the provided context object.
 *
 * @param {object} rule    - The rule node (see DSL description above).
 * @param {object} context - The context object supplied by the caller.
 * @returns {boolean}
 */
function evalRule(rule, context) {
  if (rule === null || typeof rule !== 'object') {
    throw new TypeError('Each rule must be a JSON object.');
  }

  const { op } = rule;

  if (typeof op !== 'string' || op.trim() === '') {
    throw new TypeError('Each rule must have a non-empty string "op" field.');
  }

  // --- Logical operators ---------------------------------------------------

  if (op === 'and') {
    if (!Array.isArray(rule.rules) || rule.rules.length === 0) {
      throw new TypeError('"and" rule requires a non-empty "rules" array.');
    }
    return rule.rules.every((child) => evalRule(child, context));
  }

  if (op === 'or') {
    if (!Array.isArray(rule.rules) || rule.rules.length === 0) {
      throw new TypeError('"or" rule requires a non-empty "rules" array.');
    }
    return rule.rules.some((child) => evalRule(child, context));
  }

  if (op === 'not') {
    if (!rule.rule || typeof rule.rule !== 'object') {
      throw new TypeError('"not" rule requires a nested "rule" object.');
    }
    return !evalRule(rule.rule, context);
  }

  // --- Comparison operators ------------------------------------------------
  // All comparison operators require "field" and "value".

  const COMPARISON_OPS = new Set(['eq', 'neq', 'gt', 'gte', 'lt', 'lte', 'in', 'nin', 'contains', 'startsWith', 'endsWith']);

  if (!COMPARISON_OPS.has(op)) {
    throw new TypeError(
      `Unknown operator "${op}". Allowed operators: ${[...COMPARISON_OPS, 'and', 'or', 'not'].join(', ')}.`,
    );
  }

  if (!Object.prototype.hasOwnProperty.call(rule, 'field')) {
    throw new TypeError(`Rule with op "${op}" requires a "field" property.`);
  }
  if (!Object.prototype.hasOwnProperty.call(rule, 'value')) {
    throw new TypeError(`Rule with op "${op}" requires a "value" property.`);
  }

  const actual = getField(context, rule.field);
  const expected = rule.value;

  switch (op) {
    case 'eq':  return actual === expected;
    case 'neq': return actual !== expected;

    case 'gt':  return typeof actual === 'number' && typeof expected === 'number' && actual >  expected;
    case 'gte': return typeof actual === 'number' && typeof expected === 'number' && actual >= expected;
    case 'lt':  return typeof actual === 'number' && typeof expected === 'number' && actual <  expected;
    case 'lte': return typeof actual === 'number' && typeof expected === 'number' && actual <= expected;

    case 'in':
      if (!Array.isArray(expected)) {
        throw new TypeError('"in" requires "value" to be an array.');
      }
      return expected.includes(actual);

    case 'nin':
      if (!Array.isArray(expected)) {
        throw new TypeError('"nin" requires "value" to be an array.');
      }
      return !expected.includes(actual);

    case 'contains':
      if (typeof actual !== 'string' || typeof expected !== 'string') {
        throw new TypeError('"contains" requires both the field value and "value" to be strings.');
      }
      return actual.includes(expected);

    case 'startsWith':
      if (typeof actual !== 'string' || typeof expected !== 'string') {
        throw new TypeError('"startsWith" requires both the field value and "value" to be strings.');
      }
      return actual.startsWith(expected);

    case 'endsWith':
      if (typeof actual !== 'string' || typeof expected !== 'string') {
        throw new TypeError('"endsWith" requires both the field value and "value" to be strings.');
      }
      return actual.endsWith(expected);

    // No default needed — all members of COMPARISON_OPS are handled above.
  }
}

// ---------------------------------------------------------------------------
// POST /check
//
// Request body (JSON):
//   {
//     "rule":    <rule object>,   // required
//     "context": <object>         // required — the data evaluated against
//   }
//
// Response 200:
//   { "result": true | false }
//
// Response 400:
//   { "error": "<message>" }
// ---------------------------------------------------------------------------
app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  if (rule === undefined || rule === null) {
    return res.status(400).json({ error: 'Request body must include a "rule" field.' });
  }
  if (context === undefined || context === null || typeof context !== 'object' || Array.isArray(context)) {
    return res.status(400).json({ error: 'Request body must include a "context" object.' });
  }

  try {
    const result = evalRule(rule, context);
    return res.status(200).json({ result: Boolean(result) });
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }
});

// ---------------------------------------------------------------------------
// Start server (skipped when file is require()'d by tests)
// ---------------------------------------------------------------------------
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Rules engine listening on port ${PORT}`);
  });
}

module.exports = app;

