/**
 * Evaluate a tokenised rule expression with two-level precedence:
 *   level 1 (lowest)  — logical:    &&  ||
 *   level 2 (highest) — comparison: ==  !=  >  >=  <  <=
 *
 * Grammar (EBNF):
 *   expr       : comparison (logical_op comparison)*
 *   comparison : operand    (cmp_op    operand)*
 *   operand    : literal | path
 *
 * This ensures  "ctx.x > 1 && ctx.y < 10"  is evaluated as
 *   "(ctx.x > 1) && (ctx.y < 10)"  and not left-to-right flat.
 */

const LOGICAL_OPS    = new Set(['&&', '||']);
const COMPARISON_OPS = new Set(['==', '!=', '>', '>=', '<', '<=']);

/**
 * Parse and evaluate one comparison cluster starting at tokens[pos].
 * Returns { value, pos } where pos is the index of the next unconsumed token.
