'use strict';

const express = require('express');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule engine
//
// Rules are plain JSON objects — never executed as code.
//
// A rule has the shape:
//   { "field": <string>, "op": <operator>, "value": <scalar> }
//
// Supported operators: eq, neq, gt, gte, lt, lte, in, nin, contains
//
// "field" is a dot-separated path into the context object,
// e.g. "user.age" resolves ctx.user.age.
//
// Compound rules:
//   { "and": [ <rule>, ... ] }
//   { "or":  [ <rule>, ... ] }
//   { "not": <rule> }
// ---------------------------------------------------------------------------

/**
 * Safely resolve a dot-separated field path from an object.
 * Returns undefined when any segment is missing.
 * Rejects prototype-climbing keys (__proto__, constructor, prototype).
 */
function resolvePath(obj, path) {
  const segments = path.split('.');
  let current = obj;
  for (const seg of segments) {
    if (seg === '__proto__' || seg === 'constructor' || seg === 'prototype') {
      return undefined;
    }
    if (current === null || typeof current !== 'object') {
      return undefined;
    }
    current = current[seg];
  }
  return current;
}

const ALLOWED_OPS = new Set([
  'eq', 'neq', 'gt', 'gte', 'lt', 'lte', 'in', 'nin', 'contains',
]);

/**
 * Evaluate a single leaf rule against ctx.
 * Returns a boolean, or throws a descriptive Error for invalid input.
 */
function evalLeaf(rule, ctx) {
  const { field, op, value } = rule;

  if (typeof field !== 'string' || field.trim() === '') {
    throw new Error('Rule "field" must be a non-empty string.');
  }
  if (!ALLOWED_OPS.has(op)) {
    throw new Error(
      `Unknown operator "${op}". Allowed: ${[...ALLOWED_OPS].join(', ')}.`
    );
  }

  const actual = resolvePath(ctx, field);

  switch (op) {
    case 'eq':       return actual === value;
    case 'neq':      return actual !== value;
    case 'gt':       return actual >   value;
    case 'gte':      return actual >=  value;
    case 'lt':       return actual <   value;
    case 'lte':      return actual <=  value;
    case 'in':
      if (!Array.isArray(value)) {
        throw new Error('"in" operator requires "value" to be an array.');
      }
      return value.includes(actual);
    case 'nin':
      if (!Array.isArray(value)) {
        throw new Error('"nin" operator requires "value" to be an array.');
      }
      return !value.includes(actual);
    case 'contains':
      if (typeof actual !== 'string') {
        throw new Error('"contains" operator requires the field value to be a string.');
      }
      return actual.includes(String(value));
    default:
      // Unreachable due to ALLOWED_OPS guard above, but keeps linters happy.
      throw new Error(`Unhandled operator: ${op}`);
  }
}

/**
 * Recursively evaluate a rule tree against a context object.
 * Returns a boolean.
 */
function evalRule(rule, ctx) {
  if (rule === null || typeof rule !== 'object') {
    throw new Error('Each rule must be a JSON object.');
  }

  // Compound: AND
  if (Object.prototype.hasOwnProperty.call(rule, 'and')) {
    if (!Array.isArray(rule.and) || rule.and.length === 0) {
      throw new Error('"and" must be a non-empty array of rules.');
    }
    return rule.and.every((sub) => evalRule(sub, ctx));
  }

  // Compound: OR
  if (Object.prototype.hasOwnProperty.call(rule, 'or')) {
    if (!Array.isArray(rule.or) || rule.or.length === 0) {
      throw new Error('"or" must be a non-empty array of rules.');
    }
    return rule.or.some((sub) => evalRule(sub, ctx));
  }

  // Compound: NOT
  if (Object.prototype.hasOwnProperty.call(rule, 'not')) {
    return !evalRule(rule.not, ctx);
  }

  // Leaf
  return evalLeaf(rule, ctx);
}

// ---------------------------------------------------------------------------
// POST /check
//
// Request body:
//   {
//     "rule":    <rule object — see engine above>,
//     "context": <arbitrary JSON object that rule fields are resolved against>
//   }
//
// Success response 200:
//   { "result": true | false }
//
// Error response 400:
//   { "error": "<message>" }
// ---------------------------------------------------------------------------
app.post('/check', (req, res) => {
  const { rule, context } = req.body;

  if (rule === undefined) {
    return res.status(400).json({ error: 'Missing required field: "rule".' });
  }
  if (context === undefined) {
    return res.status(400).json({ error: 'Missing required field: "context".' });
  }
  if (typeof context !== 'object' || context === null || Array.isArray(context)) {
    return res.status(400).json({ error: '"context" must be a JSON object.' });
  }

  let result;
  try {
    result = evalRule(rule, context);
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }

  return res.status(200).json({ result: Boolean(result) });
});

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`acme-rules listening on port ${PORT}`);
});

module.exports = app; // exported for testing

