'use strict';

const http = require('http');

// ─── Safe expression evaluator ───────────────────────────────────────────────

/**
 * Tokeniser
 * Converts a rule string into a flat array of tokens.
 */
function tokenise(src) {
  const tokens = [];
  let i = 0;

  while (i < src.length) {
    // Skip whitespace
    if (/\s/.test(src[i])) { i++; continue; }

    // Numbers  (integer or decimal)
    if (/[0-9]/.test(src[i]) || (src[i] === '.' && /[0-9]/.test(src[i + 1]))) {
      let num = '';
      while (i < src.length && /[0-9.]/.test(src[i])) num += src[i++];
      tokens.push({ type: 'NUMBER', value: parseFloat(num) });
      continue;
    }

    // Strings  (' or ")
    if (src[i] === '"' || src[i] === "'") {
      const quote = src[i++];
      let str = '';
      while (i < src.length && src[i] !== quote) {
        if (src[i] === '\\') {
          i++;
          const esc = { n: '\n', t: '\t', r: '\r', '\\': '\\', "'": "'", '"': '"' };
          str += esc[src[i]] ?? src[i];
        } else {
          str += src[i];
        }
        i++;
      }
      i++; // closing quote
      tokens.push({ type: 'STRING', value: str });
      continue;
    }

    // Identifiers / keywords
    if (/[a-zA-Z_$]/.test(src[i])) {
      let id = '';
      while (i < src.length && /[a-zA-Z0-9_$]/.test(src[i])) id += src[i++];
      const keywords = { true: true, false: false, null: null };
      if (id in keywords) {
        tokens.push({ type: 'LITERAL', value: keywords[id] });
      } else {
        tokens.push({ type: 'IDENT', value: id });
      }
      continue;
    }

    // Multi-char operators  (must check longer ones first)
    const multiChar = ['===', '!==', '==', '!=', '<=', '>=', '&&', '||'];
    let matched = false;
    for (const op of multiChar) {
      if (src.startsWith(op, i)) {
        tokens.push({ type: 'OP', value: op });
        i += op.length;
        matched = true;
        break;
      }
    }
    if (matched) continue;

    // Single-char punctuation
    const single = '+-*/%<>!?:.,()[]';
