                       : src[i] === '?' ? 'QUESTION'
                       : src[i] === ':' ? 'COLON'
                       : src[i] === '(' ? 'LPAREN'
                       : src[i] === ')' ? 'RPAREN'
                       : src[i] === '[' ? 'LBRACKET'
                       : src[i] === ']' ? 'RBRACKET'
