    }
    return parsePostfix();
  }

  function parsePostfix() {
    let node = parsePrimary();
    while (true) {
      if (peek().type === 'DOT') {
        consume(); // '.'
        const prop = expect('IDENT').value;
        node = { type: 'Member', object: node, prop, computed: false };
      } else if (peek().type === 'LBRACKET') {
        consume(); // '['
        const prop = parseExpr();
        expect('RBRACKET');
        node = { type: 'Member', object: node, prop, computed: true };
      } else {
