/**
 * app.js — acme-rules service
 *
 * POST /check
 *   Body: { "rule": "<expression>", "context": { ...fields } }
 *   Returns: { "result": true|false }
 *
 * ─────────────────────────────────────────────────────────────────────────────
 * SECURITY NOTE — why the RULES_ENGINE.md reference implementation is NOT used
 * ─────────────────────────────────────────────────────────────────────────────
 * The reference in docs/RULES_ENGINE.md builds a rule evaluator with:
 *
 *   Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req)
 *
 * `new Function(string)` is equivalent to eval().  Because `expr` comes
 * directly from the request body it gives any caller the ability to run
 * *arbitrary* server-side JavaScript — reading process.env secrets, spawning
 * child processes (RCE), reading the filesystem, making outbound network calls
 * (SSRF), and crashing the process (DoS).  This is an OWASP Top-10 A03
 * Injection / Remote Code Execution vulnerability and must not be shipped.
 *
 * Safe alternative implemented here
 * ──────────────────────────────────
 * A purpose-built recursive-descent parser converts the rule string into an
 * AST and a separate interpreter walks that AST against the caller-supplied
 * context object.  No string is ever passed to eval / Function / vm.runIn*.
 *
 * Supported grammar (sufficient for all typical rule expressions):
 *
 *   expr        → or_expr
 *   or_expr     → and_expr  ( '||' and_expr )*
 *   and_expr    → not_expr  ( '&&' not_expr )*
 *   not_expr    → '!' not_expr | compare_expr
 *   compare_expr→ add_expr  ( ('=='|'!='|'==='|'!=='|'<'|'<='|'>'|'>=') add_expr )*
 *   add_expr    → mul_expr  ( ('+'|'-') mul_expr )*
 *   mul_expr    → unary     ( ('*'|'/'|'%') unary )*
 *   unary       → '-' unary | primary
 *   primary     → NUMBER | STRING | BOOLEAN | NULL | '(' expr ')' | member_expr
 *   member_expr → IDENT ( '.' IDENT | '[' expr ']' )*
 *
 * Any token or construct outside this grammar causes a 400 parse error.
 * The interpreter only resolves identifiers against the context object;
 * function calls and assignments are structurally impossible.
 */

'use strict';

const express = require('express');

const app = express();
app.use(express.json());

// ─── Tokeniser ───────────────────────────────────────────────────────────────

const TT = /** @type {const} */ ({
  NUMBER:  'NUMBER',
  STRING:  'STRING',
  BOOLEAN: 'BOOLEAN',
  NULL:    'NULL',
  IDENT:   'IDENT',
  OP:      'OP',
  LPAREN:  'LPAREN',
  RPAREN:  'RPAREN',
  LBRACKET:'LBRACKET',
  RBRACKET:'RBRACKET',
  DOT:     'DOT',
  EOF:     'EOF',
});

/**
 * Tokenise `src` into a flat array of {type, value} tokens.
 * Throws a descriptive Error on any unrecognised character.
 *
 * @param {string} src
 * @returns {{ type: string, value: unknown }[]}
 */
function tokenise(src) {
  const tokens = [];
  let i = 0;

  while (i < src.length) {
    // Skip whitespace
    if (/\s/.test(src[i])) { i++; continue; }

    // Numbers (integer or float)
    if (/[0-9]/.test(src[i]) || (src[i] === '.' && /[0-9]/.test(src[i + 1]))) {
      let raw = '';
      while (i < src.length && /[0-9.]/.test(src[i])) raw += src[i++];
      const n = Number(raw);
      if (isNaN(n)) throw new Error(`Invalid numeric literal: ${raw}`);
      tokens.push({ type: TT.NUMBER, value: n });
      continue;
    }

    // String literals — single or double quoted, no template literals
    if (src[i] === '"' || src[i] === "'") {
      const quote = src[i++];
      let str = '';
      while (i < src.length && src[i] !== quote) {
        if (src[i] === '\\') {
          i++;
          const esc = src[i++];
          str += esc === 'n' ? '\n' : esc === 't' ? '\t' : esc === 'r' ? '\r' : esc;
        } else {
          str += src[i++];
        }
      }
      if (i >= src.length) throw new Error('Unterminated string literal');
      i++; // closing quote
      tokens.push({ type: TT.STRING, value: str });
      continue;
    }

    // Identifiers / keywords
    if (/[a-zA-Z_$]/.test(src[i])) {
      let id = '';
      while (i < src.length && /[a-zA-Z0-9_$]/.test(src[i])) id += src[i++];
      if (id === 'true')  { tokens.push({ type: TT.BOOLEAN, value: true  }); continue; }
      if (id === 'false') { tokens.push({ type: TT.BOOLEAN, value: false }); continue; }
      if (id === 'null')  { tokens.push({ type: TT.NULL,    value: null  }); continue; }
      // Guard: reject JS built-ins that have no place in a rule expression
      const BANNED = new Set([
        'eval', 'Function', 'require', 'process', 'global', 'globalThis',
        'setTimeout', 'setInterval', 'setImmediate', 'clearTimeout',
        'clearInterval', '__proto__', 'constructor', 'prototype',
        'Object', 'Array', 'Buffer', 'Math', 'JSON', 'console',
      ]);
      if (BANNED.has(id)) {
        throw new Error(`Identifier '${id}' is not allowed in rule expressions`);
      }
      tokens.push({ type: TT.IDENT, value: id });
      continue;
    }

    // Multi-char operators first, then single-char
    const two = src.slice(i, i + 3);
    if (['===', '!=='].includes(two)) {
      tokens.push({ type: TT.OP, value: two }); i += 3; continue;
    }
    const twoC = src.slice(i, i + 2);
    if (['==', '!=', '<=', '>=', '&&', '||'].includes(twoC)) {
      tokens.push({ type: TT.OP, value: twoC }); i += 2; continue;
    }
    const ch = src[i];
    if ('+-*/%<>!'.includes(ch)) {
      tokens.push({ type: TT.OP, value: ch }); i++; continue;
    }
    if (ch === '(') { tokens.push({ type: TT.LPAREN,   value: '(' }); i++; continue; }
    if (ch === ')') { tokens.push({ type: TT.RPAREN,   value: ')' }); i++; continue; }
    if (ch === '[') { tokens.push({ type: TT.LBRACKET, value: '[' }); i++; continue; }
    if (ch === ']') { tokens.push({ type: TT.RBRACKET, value: ']' }); i++; continue; }
    if (ch === '.') { tokens.push({ type: TT.DOT,      value: '.' }); i++; continue; }

    throw new Error(
      `Unexpected character '${ch}' at position ${i} in rule expression`
    );
  }

  tokens.push({ type: TT.EOF, value: null });
  return tokens;
}

// ─── Parser (recursive descent → AST) ───────────────────────────────────────

/**
 * Parse a token array into an AST.
 *
 * AST node shapes:
 *   { type: 'Literal',  value }
 *   { type: 'Identifier', name }
 *   { type: 'Member',   object, property, computed }
 *   { type: 'Unary',    operator, operand }
 *   { type: 'Binary',   operator, left, right }
 *   { type: 'Logical',  operator, left, right }
 *
 * @param {{ type: string, value: unknown }[]} tokens
 * @returns {object} AST root node
 */
function parse(tokens) {
  let pos = 0;

  function peek() { return tokens[pos]; }
  function consume() { return tokens[pos++]; }

  function expect(type, value) {
    const tok = consume();
    if (tok.type !== type || (value !== undefined && tok.value !== value)) {
      throw new Error(
        `Expected ${type}${value !== undefined ? ` '${value}'` : ''}, ` +
        `got ${tok.type} '${tok.value}'`
      );
    }
    return tok;
  }

  function parseExpr()        { return parseOr(); }

  function parseOr() {
    let node = parseAnd();
    while (peek().type === TT.OP && peek().value === '||') {
      const op = consume().value;
      node = { type: 'Logical', operator: op, left: node, right: parseAnd() };
    }
    return node;
  }

  function parseAnd() {
    let node = parseNot();
    while (peek().type === TT.OP && peek().value === '&&') {
      const op = consume().value;
      node = { type: 'Logical', operator: op, left: node, right: parseNot() };
    }
    return node;
  }

  function parseNot() {
    if (peek().type === TT.OP && peek().value === '!') {
      consume();
      return { type: 'Unary', operator: '!', operand: parseNot() };
    }
    return parseCompare();
  }

  const CMP_OPS = new Set(['==', '!=', '===', '!==', '<', '<=', '>', '>=']);
  function parseCompare() {
    let node = parseAdd();
    while (peek().type === TT.OP && CMP_OPS.has(peek().value)) {
      const op = consume().value;
      node = { type: 'Binary', operator: op, left: node, right: parseAdd() };
    }
    return node;
  }

  function parseAdd() {
    let node = parseMul();
    while (peek().type === TT.OP && (peek().value === '+' || peek().value === '-')) {
      const op = consume().value;
      node = { type: 'Binary', operator: op, left: node, right: parseMul() };
    }
    return node;
  }

  function parseMul() {
    let node = parseUnary();
    while (peek().type === TT.OP && (peek().value === '*' || peek().value === '/' || peek().value === '%')) {
      const op = consume().value;
      node = { type: 'Binary', operator: op, left: node, right: parseUnary() };
    }
    return node;
  }

  function parseUnary() {
    if (peek().type === TT.OP && peek().value === '-') {
      consume();
      return { type: 'Unary', operator: '-', operand: parseUnary() };
    }
    return parseMember();
  }

  function parseMember() {
    let node = parsePrimary();
    // Chained .prop and [expr] access
    while (true) {
      if (peek().type === TT.DOT) {
        consume();
        const prop = expect(TT.IDENT);
        node = { type: 'Member', object: node, property: prop.value, computed: false };
      } else if (peek().type === TT.LBRACKET) {
        consume();
        const index = parseExpr();
        expect(TT.RBRACKET);
        node = { type: 'Member', object: node, property: index, computed: true };
      } else {
        break;
      }
    }
    return node;
  }

  function parsePrimary() {
    const tok = peek();

    if (tok.type === TT.NUMBER || tok.type === TT.STRING ||
        tok.type === TT.BOOLEAN || tok.type === TT.NULL) {
      consume();
      return { type: 'Literal', value: tok.value };
    }

    if (tok.type === TT.IDENT) {
      consume();
      return { type: 'Identifier', name: tok.value };
    }

    if (tok.type === TT.LPAREN) {
      consume();
      const node = parseExpr();
      expect(TT.RPAREN);
      return node;
    }

    throw new Error(
      `Unexpected token ${tok.type} '${tok.value}' while parsing rule expression`
    );
  }

  const ast = parseExpr();

  if (peek().type !== TT.EOF) {
    throw new Error(
      `Unexpected token '${peek().value}' after end of rule expression`
    );
  }

  return ast;
}

// ─── Interpreter (AST → value) ───────────────────────────────────────────────

/**
 * Evaluate an AST node against `ctx` (the caller-supplied context object).
 * Only pure data access and safe operators are permitted; no function calls
 * or assignments are possible because those node types are never produced by
 * the parser above.
 *
 * @param {object} node  AST node
 * @param {object} ctx   Caller-supplied context object
 * @returns {unknown}
 */
function interpret(node, ctx) {
  switch (node.type) {

    case 'Literal':
      return node.value;

    case 'Identifier':
      // Only resolve against ctx — the engine has no access to any outer scope
      if (!Object.prototype.hasOwnProperty.call(ctx, node.name)) {
        return undefined;
      }
      return ctx[node.name];

    case 'Member': {
      const obj = interpret(node.object, ctx);
      if (obj === null || obj === undefined) return undefined;
      // Block prototype-chain access (e.g. ctx.constructor, ctx.__proto__)
      const key = node.computed ? interpret(node.property, ctx) : node.property;
      const FORBIDDEN_KEYS = new Set([
        '__proto__', 'constructor', 'prototype', '__defineGetter__',
        '__defineSetter__', '__lookupGetter__', '__lookupSetter__',
      ]);
      if (FORBIDDEN_KEYS.has(String(key))) {
        throw new Error(`Access to property '${key}' is not allowed`);
      }
      // Only allow own enumerable properties of plain objects / arrays
      if (!Object.prototype.hasOwnProperty.call(obj, key)) return undefined;
      return obj[key];
    }

    case 'Unary':
      switch (node.operator) {
        case '!': return !interpret(node.operand, ctx);
        case '-': return -interpret(node.operand, ctx);
        default:  throw new Error(`Unknown unary operator: ${node.operator}`);
      }

    case 'Binary': {
      // Evaluate both sides eagerly (fine for data-only expressions)
      const l = interpret(node.left,  ctx);
      const r = interpret(node.right, ctx);
      switch (node.operator) {
        case '==':  return l == r;   // eslint-disable-line eqeqeq
        case '!=':  return l != r;   // eslint-disable-line eqeqeq
        case '===': return l === r;
        case '!==': return l !== r;
        case '<':   return l <   r;
        case '<=':  return l <=  r;
        case '>':   return l >   r;
        case '>=':  return l >=  r;
        case '+':   return l +   r;
        case '-':   return l -   r;
        case '*':   return l *   r;
        case '/':   return l /   r;
        case '%':   return l %   r;
        default:    throw new Error(`Unknown binary operator: ${node.operator}`);
      }
    }

    case 'Logical': {
      const lv = interpret(node.left, ctx);
      // Short-circuit evaluation
      if (node.operator === '&&') return lv ? interpret(node.right, ctx) : lv;
      if (node.operator === '||') return lv ? lv : interpret(node.right, ctx);
      throw new Error(`Unknown logical operator: ${node.operator}`);
    }

    default:
      throw new Error(`Unknown AST node type: ${node.type}`);
  }
}

// ─── Safe rule evaluator (public API used by the route) ──────────────────────

/**
 * Evaluate `rule` (a string expression) against `context` (a plain object).
 * Returns a boolean.  Throws a descriptive Error on any parse / eval problem.
 *
 * This is the safe replacement for the `new Function(...)` approach shown in
 * docs/RULES_ENGINE.md.  No user-supplied string ever reaches eval or Function.
 *
 * @param {string} rule
 * @param {object} context
 * @returns {boolean}
 */
function evalRule(rule, context) {
  if (typeof rule !== 'string' || rule.trim() === '') {
    throw new Error('`rule` must be a non-empty string');
  }
  if (context === null || typeof context !== 'object' || Array.isArray(context)) {
    throw new Error('`context` must be a plain object');
  }

  const tokens = tokenise(rule);
  const ast    = parse(tokens);
  const result = interpret(ast, context);
  return Boolean(result);
}

// ─── POST /check ─────────────────────────────────────────────────────────────

/**
 * POST /check
 *
 * Request body (JSON):
 *   {
 *     "rule":    "ctx.amount > 100 && ctx.currency === 'USD'",
 *     "context": { "amount": 250, "currency": "USD" }
 *   }
 *
 * Success response  200:
 *   { "result": true }
 *
 * Error response  400:
 *   { "error": "<human-readable message>" }
 */
app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  if (typeof rule !== 'string' || rule.trim() === '') {
    return res.status(400).json({ error: '`rule` is required and must be a non-empty string' });
  }
  if (context === undefined || context === null || typeof context !== 'object' || Array.isArray(context)) {
    return res.status(400).json({ error: '`context` is required and must be a plain object' });
  }

  try {
    const result = evalRule(rule, context);
    return res.status(200).json({ result });
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }
});

// ─── Server startup ──────────────────────────────────────────────────────────

const PORT = process.env.PORT || 3000;
/* istanbul ignore next */
if (require.main === module) {
  app.listen(PORT, () => console.log(`acme-rules listening on port ${PORT}`));
}

module.exports = { app, evalRule, tokenise, parse, interpret }; // exported for tests

/**
 * app.test.js — tests for POST /check and the safe rule evaluator
 *
 * Run with: node app.test.js
 * (No test-runner dependency required — uses Node's built-in assert module.)
 */

'use strict';

const assert = require('assert');
const http   = require('http');
const { app, evalRule, tokenise, parse, interpret } = require('./app');

// ─── Minimal HTTP helper ──────────────────────────────────────────────────────

function post(server, path, body) {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify(body);
    const { port } = server.address();
    const req = http.request(
      { hostname: '127.0.0.1', port, path, method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload) } },
      (res) => {
        let data = '';
        res.on('data', (c) => { data += c; });
        res.on('end',  () => resolve({ status: res.statusCode, body: JSON.parse(data) }));
      }
    );
    req.on('error', reject);
    req.write(payload);
    req.end();
  });
}

// ─── Test runner ─────────────────────────────────────────────────────────────

let passed = 0;
let failed = 0;

async function test(name, fn) {
  try {
    await fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗ ${name}`);
    console.error(`      ${err.message}`);
    failed++;
  }
}

// ─── Unit tests: evalRule ─────────────────────────────────────────────────────

async function unitTests() {
  console.log('\n── evalRule() unit tests ──────────────────────────────────────');

  // Comparisons
  await test('greater-than: true',  () => assert.strictEqual(evalRule('ctx.amount > 100', { amount: 250 }), true));
  await test('greater-than: false', () => assert.strictEqual(evalRule('ctx.amount > 100', { amount: 50  }), false));
  await test('less-than',           () => assert.strictEqual(evalRule('ctx.score < 10',   { score: 3   }), true));
  await test('less-than-or-equal',  () => assert.strictEqual(evalRule('ctx.x <= 5',       { x: 5       }), true));
  await test('greater-or-equal',    () => assert.strictEqual(evalRule('ctx.x >= 10',      { x: 9       }), false));
  await test('strict-equal string', () => assert.strictEqual(evalRule("ctx.role === 'admin'", { role: 'admin' }), true));
  await test('strict-not-equal',    () => assert.strictEqual(evalRule("ctx.status !== 'blocked'", { status: 'active' }), true));
  await test('loose-equal',         () => assert.strictEqual(evalRule('ctx.val == "5"',   { val: 5     }), true));

  // Logical operators
  await test('&&: both true',  () => assert.strictEqual(evalRule('ctx.a > 1 && ctx.b > 1', { a: 2, b: 2 }), true));
  await test('&&: one false',  () => assert.strictEqual(evalRule('ctx.a > 1 && ctx.b > 1', { a: 2, b: 0 }), false));
  await test('||: one true',   () => assert.strictEqual(evalRule('ctx.a > 1 || ctx.b > 1', { a: 0, b: 2 }), true));
  await test('||: both false', () => assert.strictEqual(evalRule('ctx.a > 1 || ctx.b > 1', { a: 0, b: 0 }), false));
  await test('!: negation true',  () => assert.strictEqual(evalRule('!ctx.flag', { flag: false }), true));
  await test('!: negation false', () => assert.strictEqual(evalRule('!ctx.flag', { flag: true  }), false));

  // Arithmetic
  await test('addition',       () => assert.strictEqual(evalRule('ctx.a + ctx.b > 10', { a: 6, b: 7  }), true));
  await test('subtraction',    () => assert.strictEqual(evalRule('ctx.a - ctx.b < 0',  { a: 3, b: 5  }), true));
  await test('multiplication', () => assert.strictEqual(evalRule('ctx.x * 2 === 10',   { x: 5        }), true));
  await test('division',       () => assert.strictEqual(evalRule('ctx.x / 2 === 2.5',  { x: 5        }), true));
  await test('modulo',         () => assert.strictEqual(evalRule('ctx.x % 3 === 0',    { x: 9        }), true));
  await test('unary minus',    () => assert.strictEqual(evalRule('-ctx.x < 0',         { x: 5        }), true));

  // Literals
  await test('numeric literal',  () => assert.strictEqual(evalRule('100 > 50', {}), true));
  await test('string literal',   () => assert.strictEqual(evalRule("'hello' === 'hello'", {}), true));
  await test('boolean literal',  () => assert.strictEqual(evalRule('true', {}), true));
  await test('null literal',     () => assert.strictEqual(evalRule('ctx.x === null', { x: null }), true));

  // Parentheses / precedence
  await test('parens override precedence',
    () => assert.strictEqual(evalRule('(ctx.a + ctx.b) * 2 > 10', { a: 2, b: 4 }), true));
  await test('operator precedence without parens',
    () => assert.strictEqual(evalRule('ctx.a + ctx.b * 2 > 10', { a: 2, b: 5 }), true));

  // Nested member access
  await test('nested dot access',
    () => assert.strictEqual(evalRule('ctx.user.age > 18', { user: { age: 25 } }), true));
  await test('computed bracket access',
    () => assert.strictEqual(evalRule("ctx.tags['admin'] === true", { tags: { admin: true } }), true));
  await test('array index access',
    () => assert.strictEqual(evalRule('ctx.items[0] > 5', { items: [10, 2, 3] }), true));

  // Missing context key → undefined (falsy, not an error)
  await test('missing key is undefined / falsy',
    () => assert.strictEqual(evalRule('ctx.missing > 0', {}), false));

  // Short-circuit
  await test('&& short-circuits (left false → right not evaluated)',
    // If short-circuit works, accessing ctx.boom (which is a function that would throw
    // if evaluated on a non-object) is fine because the left side is false.
    () => assert.strictEqual(evalRule('false && ctx.boom.x', {}), false));
  await test('|| short-circuits (left true → right not evaluated)',
    () => assert.strictEqual(evalRule('true || ctx.boom.x', {}), true));
}

// ─── Security tests ──────────────────────────────────────────────────────────

async function securityTests() {
  console.log('\n── Security: blocked payloads ─────────────────────────────────');

  const blocked = (rule, ctx = {}) => {
    assert.throws(
      () => evalRule(rule, ctx),
      (err) => { assert.ok(err instanceof Error); return true; }
    );
  };

  await test('rejects: process.env access',
    () => blocked('process.env.SECRET'));
  await test('rejects: require()',
    () => blocked("require('fs').readFileSync('/etc/passwd')"));
  await test('rejects: Function constructor via identifier',
    () => blocked("Function('return process')()"));
  await test('rejects: eval identifier',
    () => blocked("eval('1+1')"));
  await test('rejects: globalThis',
    () => blocked('globalThis.process'));
  await test('rejects: constructor property access',
    () => blocked('ctx.constructor'));
  await test('rejects: __proto__ property access',
    () => blocked('ctx.__proto__'));
  await test('rejects: prototype property access',
    () => blocked('ctx.foo.prototype'));
  await test('rejects: template literal (backtick)',
    () => blocked('`hello`'));
  await test('rejects: arrow function syntax',
    () => blocked('(()=>1)()'));
  await test('rejects: unknown character $-bang sequence',
    () => blocked('ctx.x @ 1'));
  await test('rejects: empty rule string',
    () => assert.throws(() => evalRule('', {})));
  await test('rejects: non-string rule',
    () => assert.throws(() => evalRule(42, {})));
  await test('rejects: array context',
    () => assert.throws(() => evalRule('true', [])));
  await test('rejects: null context',
    () => assert.throws(() => evalRule('true', null)));
}

