      const op = consume().value;
      const right = parseUnary();
      left = { type: 'BinaryOp', op, left, right };
    }
    return left;
  }

  function parseUnary() {
    if (peek().type === TT.OP && peek().value === '!') {
      consume();
      return { type: 'UnaryOp', op: '!', operand: parseUnary() };
    }
    // Unary minus for numeric literals, e.g. -1
    if (peek().type === TT.OP && peek().value === '-') {
      consume();
      const operand = parsePrimary();
      if (operand.type !== 'Literal' || typeof operand.value !== 'number') {
        throw new SyntaxError('Unary minus is only supported on numeric literals');
      }
      return { type: 'Literal', value: -operand.value };
    }
    return parsePrimary();
  }

